package com.leetcode.backend.controller;
import com.leetcode.backend.model.AssessmentEnums; import com.leetcode.backend.service.AssessmentCreatorService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.nio.charset.StandardCharsets; import java.util.*;
@RestController @RequestMapping("/api/admin/assessment-creators") public class AdminAssessmentCreatorController {private final AssessmentCreatorService service;AdminAssessmentCreatorController(AssessmentCreatorService s){service=s;}@GetMapping public List<Map<String,Object>> list(@RequestParam(defaultValue="PENDING_ADMIN_REVIEW") String status){return service.adminList(status);}@PostMapping("/{id}/approve") public Map<String,Object> approve(Authentication a,@PathVariable Long id){return service.decide(a.getName(),id,AssessmentEnums.CreatorStatus.APPROVED,null);}@PostMapping("/{id}/reject") public Map<String,Object> reject(Authentication a,@PathVariable Long id,@RequestBody Map<String,String>b){return service.decide(a.getName(),id,AssessmentEnums.CreatorStatus.REJECTED,b.get("reason"));}@PostMapping("/{id}/revoke") public Map<String,Object> revoke(Authentication a,@PathVariable Long id,@RequestBody(required=false) Map<String,String>b){return service.decide(a.getName(),id,AssessmentEnums.CreatorStatus.REVOKED,b==null?null:b.get("reason"));}@GetMapping("/{id}/document") public ResponseEntity<byte[]> document(@PathVariable Long id){var d=service.document(id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.type())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename*=UTF-8''"+java.net.URLEncoder.encode(d.name(),StandardCharsets.UTF_8)).body(d.bytes());}}
